import React, { useState, useContext, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import { initAdmin, checkAdmin, resetAdminPassword } from '../services/api';

const Login = () => {
  const navigate = useNavigate();
  const { login, isAuthenticated, error: authError, loading } = useContext(AuthContext);
  
  const [formData, setFormData] = useState({
    username: '',
    password: ''
  });
  const [error, setError] = useState(null);
  const [initMessage, setInitMessage] = useState(null);
  const [initLoading, setInitLoading] = useState(false);
  const [adminStatus, setAdminStatus] = useState(null);
  const [checkingAdmin, setCheckingAdmin] = useState(false);
  const [resettingPassword, setResettingPassword] = useState(false);

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated) {
      navigate('/');
    }
  }, [isAuthenticated, navigate]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    
    // Basic validation
    if (!formData.username || !formData.password) {
      setError('Please enter both username and password');
      return;
    }
    
    // Attempt login
    const success = await login(formData.username, formData.password);
    
    if (success) {
      navigate('/');
    }
  };

  const handleInitAdmin = async () => {
    setInitLoading(true);
    setInitMessage(null);
    setError(null);
    
    try {
      const response = await initAdmin();
      setInitMessage(response.message || 'Admin user created successfully. Username: dumpster, Password: absolutemorality');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to initialize admin user. It may already exist.');
    } finally {
      setInitLoading(false);
    }
  };

  const handleCheckAdmin = async () => {
    setCheckingAdmin(true);
    setError(null);
    setInitMessage(null);
    setAdminStatus(null);
    
    try {
      const response = await checkAdmin();
      setAdminStatus(response);
    } catch (err) {
      if (err.response?.status === 404) {
        setAdminStatus({ exists: false, message: 'Admin user does not exist' });
      } else {
        setError('Failed to check admin status. Please try again.');
      }
    } finally {
      setCheckingAdmin(false);
    }
  };

  const handleResetPassword = async () => {
    setResettingPassword(true);
    setError(null);
    setInitMessage(null);
    
    try {
      const response = await resetAdminPassword();
      setInitMessage(response.message || 'Admin password reset successfully to: absolutemorality');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to reset admin password.');
    } finally {
      setResettingPassword(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <h1 className="login-title">Login</h1>
        
        {(error || authError) && (
          <div className="error-message">
            {error || authError}
          </div>
        )}
        
        {initMessage && (
          <div className="success-message">
            {initMessage}
          </div>
        )}
        
        {adminStatus && (
          <div className={adminStatus.exists ? "success-message" : "warning-message"}>
            {adminStatus.message}
            {adminStatus.exists && (
              <div className="admin-details">
                <p>Username: {adminStatus.admin.username}</p>
                <p>Created: {new Date(adminStatus.admin.createdAt).toLocaleString()}</p>
              </div>
            )}
          </div>
        )}
        
        <form className="login-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              type="text"
              id="username"
              name="username"
              className="form-control"
              value={formData.username}
              onChange={handleChange}
              placeholder="Enter username"
              disabled={loading}
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              name="password"
              className="form-control"
              value={formData.password}
              onChange={handleChange}
              placeholder="Enter password"
              disabled={loading}
            />
          </div>
          
          <button 
            type="submit" 
            className="btn login-btn"
            disabled={loading}
          >
            {loading ? 'Logging in...' : 'Login'}
          </button>
        </form>
        
        <div className="init-admin-section">
          <p>First time setup? Initialize the admin account:</p>
          <button 
            className="btn btn-secondary init-btn"
            onClick={handleInitAdmin}
            disabled={initLoading}
          >
            {initLoading ? 'Initializing...' : 'Initialize Admin User'}
          </button>
          <small className="form-text">
            This will create an admin user with username: dumpster and password: absolutemorality
          </small>
          
          <div className="admin-tools">
            <button 
              className="btn btn-info admin-tool-btn"
              onClick={handleCheckAdmin}
              disabled={checkingAdmin}
            >
              {checkingAdmin ? 'Checking...' : 'Check Admin Status'}
            </button>
            
            <button 
              className="btn btn-warning admin-tool-btn"
              onClick={handleResetPassword}
              disabled={resettingPassword}
            >
              {resettingPassword ? 'Resetting...' : 'Reset Admin Password'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
